package com.franco.desco.application.delivery.service;import com.franco.desco.application.delivery.*;import com.franco.desco.application.delivery.port.in.DeliveryUseCase;import com.franco.desco.application.delivery.port.out.DeliveryPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.delivery.DeliveryModels;
public final class DeliveryApplicationService implements DeliveryUseCase{private final DeliveryPersistencePort p;public DeliveryApplicationService(DeliveryPersistencePort p){this.p=p;}public AppResult<PageResult<DeliveryModels.Summary>>list(DeliveryCommands.ListDeliveries c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"ENTREGAS_LISTADAS","ENTREGAS_NO_LISTADAS",AppStatus.BAD_REQUEST);}public AppResult<DeliveryModels.Detail>get(DeliveryCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"ENTREGA_CONSULTADA","ENTREGA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>create(DeliveryCommands.Create c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"ENTREGA_REGISTRADA","ENTREGA_NO_REGISTRADA");}public AppResult<Void>updatePreliminary(DeliveryCommands.UpdatePreliminary c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.updatePreliminary(c,i,m),"ENTREGA_ACTUALIZADA","ENTREGA_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void>confirm(DeliveryCommands.Confirm c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.confirm(c,i,m),"ENTREGA_CONFIRMADA","ENTREGA_NO_CONFIRMADA",AppStatus.BAD_REQUEST);}public AppResult<Void>annul(DeliveryCommands.Annul c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.annul(c,i,m),"ENTREGA_ANULADA","ENTREGA_NO_ANULADA",AppStatus.BAD_REQUEST);}}
